function su(e,n){if(n){if(n.type==="classifier")return`Classifier '${n.classifier}' requires approval for this ${e} command: ${n.reason}`;switch(n.type){case"hook":return n.reason?`Hook '${n.hookName}' blocked this action: ${n.reason}`:`Hook '${n.hookName}' requires approval for this ${e} command`;case"rule":{let s=Wn(n.rule.ruleValue),g=vfe(n.rule.source);return`Permission rule '${s}' from ${g} requires approval for this ${e} command`}case"subcommandResults":{let s=[];for(let[g,h]of n.reasons)if(h.behavior==="ask"||h.behavior==="passthrough")if(e==="Bash"){let{commandWithoutRedirections:y,redirections:w}=Spe(g),O=w.length>0?y:g;s.push(O)}else s.push(g);if(s.length>0){let g=s.length;return`This ${e} command contains multiple operations. The following ${P(g,"part")} ${P(g,"requires","require")} approval: ${s.join(", ")}`}return`This ${e} command contains multiple operations that require approval`}case"permissionPromptTool":return`Tool '${n.permissionPromptToolName}' requires approval for this ${e} command`;case"sandboxOverride":return"Run outside of the sandbox";case"workingDir":return n.reason;case"safetyCheck":case"other":return n.reason;case"mode":return`Current permission mode (${wq(n.mode)}) requires approval for this ${e} command`;case"asyncAgent":return n.reason}}return`Claude requested permissions to use ${e}, but you haven't granted it yet.`}
